import{it as e,n as t,rt as n,vt as r}from"./chunks/framework.BQh0MzVE.js";var i=JSON.parse(`{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"pages/overview.md","filePath":"pages/overview.md"}`),a={name:`pages/overview.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h1><p>SQL Exporter is a configuration-driven exporter that exposes metrics gathered from databases, for use by the Prometheus monitoring system.</p><p>Per the Prometheus philosophy, scrapes are <strong>synchronous</strong> (i.e. metrics are collected on every <code>/metrics</code> poll). However, to keep load at reasonable levels, minimum collection intervals may optionally be set per collector, producing cached metrics when queried more frequently than the configured interval.</p><h2 id="why-it-exists" tabindex="-1">Why it exists <a class="header-anchor" href="#why-it-exists" aria-label="Permalink to “Why it exists”">​</a></h2><p>Originally, SQL Exporter started off as an exporter for <code>Microsoft SQL Server</code>, for which no reliable exporters existed.</p><p>But what is the point of a configuration-driven SQL exporter, if you&#39;re going to use it along with 2 more exporters with wholly different world views and configurations, because you also have <code>MySQL</code> and <code>PostgreSQL</code> instances to monitor?..</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><p>Some alternative database agnostic exporters are available. They both do the collection at fixed intervals, independent of Prometheus scrapes. This is partly a philosophical issue, but practical issues are not all that difficult to imagine:</p><ul><li>jitter;</li><li>duplicate data points;</li><li>collected but not scraped data points.</li></ul><p>The control they provide over which labels get applied is limited, and the base label set spammy. And finally, configurations are not easily reused without copy-pasting and editing across jobs and instances.</p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to “Credits”">​</a></h2><p>This is a fork of the original solution created by <a href="https://github.com/free/sql_exporter" target="_blank" rel="noreferrer">@free</a> that was abandoned in 2019. The development since has been taken over by <a href="https://github.com/burningalchemist" target="_blank" rel="noreferrer">@burningalchemist</a>, who maintains and supports it in their free time.</p><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to “”">​</a></h2>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};